const fs = require('fs');
const path = require('path');

function shellQuote(value) {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

// Do not execute shell configuration just to inspect it. Match only literal
// assignments generated by CocoaPods (including Shellwords-escaped paths).
function literalNodeAssignment(line) {
  const match = line.match(/^([ \t]*(?:export[ \t]+)?NODE_BINARY[ \t]*=[ \t]*)(?:'((?:[^']|'\\'')*)'|"([^"$`\\]*)"|((?:\\[^\r\n]|[^ \t'"\\$`;|&<>()])+))([ \t]*(?:#[^\r\n]*)?)$/);
  if (!match) return null;
  const value = match[2]?.replaceAll("'\\''", "'") ?? match[3] ?? match[4].replace(/\\(.)/g, '$1');
  if (value !== 'node' && !path.isAbsolute(value)) return null;
  return {prefix: match[1], suffix: match[5]};
}

function syncIosNodeEnvironment(iosDir, nodeBinary = process.execPath) {
  if (!path.isAbsolute(nodeBinary) || /[\r\n\0]/.test(nodeBinary)) {
    throw new Error('The selected Node executable must be an absolute, single-line path.');
  }
  const file = path.join(iosDir, '.xcode.env.local');
  let stat;
  try {
    stat = fs.lstatSync(file);
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (stat?.isSymbolicLink()) {
    return {changed: false, preservedCustom: true};
  }
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  const newline = current.includes('\r\n') ? '\r\n' : '\n';
  const lines = current.split(newline);
  const assignments = lines
    .map((line, index) => ({line, index}))
    .filter(({line}) => !/^[ \t]*#/.test(line) && /\bNODE_BINARY[ \t]*=/.test(line));
  if (assignments.some(({line}) => !literalNodeAssignment(line))) {
    // An app owns dynamic resolvers such as $(command -v node), nvm setup,
    // parameter expansion, or conditional commands; never rewrite those.
    return {changed: false, preservedCustom: true};
  }
  let updated;
  if (assignments.length > 0) {
    for (const {line, index} of assignments) {
      const {prefix, suffix} = literalNodeAssignment(line);
      lines[index] = `${prefix}${shellQuote(nodeBinary)}${suffix}`;
    }
    updated = lines.join(newline);
  } else {
    updated = current + (current && !current.endsWith(newline) ? newline : '')
      + `export NODE_BINARY=${shellQuote(nodeBinary)}${newline}`;
  }
  if (updated === current) return {changed: false, preservedCustom: false};
  fs.writeFileSync(file, updated, 'utf8');
  return {changed: true, preservedCustom: false};
}

module.exports = {syncIosNodeEnvironment};
